function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Central hub pops first
  const sHub = spr(tf, 0, 0.8, 10);
  cards[1].style.opacity = clamp(sHub * 2);
  cards[1].style.transform = `scale(${lerp(0.8, 1, sHub)})`;

  // Lines and related cards
  const sL0 = spr(tf, 0.4, 0.9, 8);
  lines[0].el.style.strokeDashoffset = lines[0].len * (1 - sL0);
  cards[0].style.opacity = clamp(sL0 * 2);
  cards[0].style.transform = `translateY(${lerp(20, 0, sL0)}px) scale(${lerp(0.9, 1, sL0)})`;

  const sL1 = spr(tf, 0.8, 0.9, 8);
  lines[1].el.style.strokeDashoffset = lines[1].len * (1 - sL1);
  cards[2].style.opacity = clamp(sL1 * 2);
  cards[2].style.transform = `translateX(${lerp(20, 0, sL1)}px) scale(${lerp(0.9, 1, sL1)})`;

  const sL2 = spr(tf, 1.0, 0.9, 8);
  lines[2].el.style.strokeDashoffset = lines[2].len * (1 - sL2);
  cards[3].style.opacity = clamp(sL2 * 2);
  cards[3].style.transform = `translateX(${lerp(-20, 0, sL2)}px) scale(${lerp(0.9, 1, sL2)})`;

  // Star count
  const sSt = spr(tf, 1.4, 0.8, 10);
  stars.style.opacity = clamp(sSt * 2);
  stars.style.transform = `translateY(${lerp(30, 0, sSt)}px)`;
  const count = Math.floor(lerp(0, 147523, E_OUT(clamp((tf - 1.4) * 0.8))));
  stars.textContent = count.toLocaleString() + ' GITHUB STARS';
}
